let dt;
let entities;
let p1_pos;
let p1_rend;
let p1_vel;
let p2_pos;
let p2_rend;
let p2_vel;
let p3_pos;
let p3_rend;
let p3_vel;
let p4_pos;
let p4_rend;
let p4_vel;
let p5_pos;
let p5_rend;
let p5_vel;
let pos;

function renderUI() {
  document.getElementById("app").innerHTML = `<p></p>`;
}

function batchUpdate(fn) {
  fn();
  renderUI();
}

function motion_system() {
  p1_pos = {x: p1_pos.x + p1_vel.x * dt, y: p1_pos.y + p1_vel.y * dt};
  p2_pos = {x: p2_pos.x + p2_vel.x * dt, y: p2_pos.y + p2_vel.y * dt};
  p3_pos = {x: p3_pos.x + p3_vel.x * dt, y: p3_pos.y + p3_vel.y * dt};
  p4_pos = {x: p4_pos.x + p4_vel.x * dt, y: p4_pos.y + p4_vel.y * dt};
  p5_pos = {x: p5_pos.x + p5_vel.x * dt, y: p5_pos.y + p5_vel.y * dt};
}

batchUpdate(function() {
  dt = 0.1;
  p1_pos = {x: 0.0, y: 0.0};
  p1_vel = {x: 10.0, y: 5.0};
  p1_rend = {color: "#ff0000"};
  sim.entity("particle1", [p1_pos, p1_vel, p1_rend]);
  p2_pos = {x: 5.0, y: 5.0};
  p2_vel = {x: -(3.0), y: 2.0};
  p2_rend = {color: "#00ff00"};
  sim.entity("particle2", [p2_pos, p2_vel, p2_rend]);
  p3_pos = {x: -(2.0), y: 3.0};
  p3_vel = {x: 1.0, y: -(4.0)};
  p3_rend = {color: "#0000ff"};
  sim.entity("particle3", [p3_pos, p3_vel, p3_rend]);
  p4_pos = {x: 10.0, y: -(2.0)};
  p4_vel = {x: -(1.0), y: -(1.0)};
  p4_rend = {color: "#ffff00"};
  sim.entity("particle4", [p4_pos, p4_vel, p4_rend]);
  p5_pos = {x: -(5.0), y: -(5.0)};
  p5_vel = {x: 2.0, y: 3.0};
  p5_rend = {color: "#ff00ff"};
  sim.entity("particle5", [p5_pos, p5_vel, p5_rend]);
  sim.system("motion", motion_system, "every frame");
  sim.run(20);
  entities = sim.query("Render");
  for (const e of entities) {
  pos = sim.get(e, "Position");
  console.log("Entity " + e + ": (" + pos.x + ", " + pos.y + ")");
}
});

function bindClicks() {
  document.getElementById("app").addEventListener("click", function(e) {
    const el = e.target.closest("[click]");
    if (!el) return;
    const fn = window[el.getAttribute("click")];
    if (typeof fn === "function") batchUpdate(fn);
  });
}
bindClicks();
